function drawNightLights(){const g=ctx;state.builds.filter(b=>b.type==='turret').forEach(b=>{g.fillStyle='#d6e0a5';g.beginPath();g.arc((b.x+.5)*C,(b.y+.5)*C,3,0,7);g.fill()})}
function startPhase(){state.phase='night';state.phaseTime=20;state.spawnTimer=.8;$('statusLine').textContent='The infected are coming — defend the tower!';showToast('SUNDOWN — the horde is on the move.');updateHud()}
function morning(){state.phase='day';state.day++;if(state.day>6){finish(true);return}state.phaseTime=18;state.zombies=[];state.wood+=12;state.scrap+=8;state.food+=6;state.tower.hp=Math.min(100,state.tower.hp+8);state.players.forEach(p=>p.hp=Math.min(100,p.hp+12));$('statusLine').textContent='Morning! Supplies recovered. Reinforce before sundown.';showToast('DAWN — supplies recovered.');updateHud();updateCards()}
function spawnZombie(){const edge=Math.floor(Math.random()*4);let x,y;if(edge===0){x=rand(1,cols-2);y=.1}else if(edge===1){x=rand(1,cols-2);y=rows-1.1}else if(edge===2){x=.1;y=rand(1,rows-2)}else{x=cols-1.1;y=rand(1,rows-2)}state.zombies.push({x,y,hp:state.day===6&&Math.random()<.14?95:38,speed:state.day===6&&Math.random()<.14?.34:rand(.35,.52),cool:rand(.2,.8),hit:0,boss:false});const z=state.zombies[state.zombies.length-1];z.boss=z.hp>50;}
function nearestZombie(x,y,range=99){let best=null,bd=range;for(const z of state.zombies){const d=Math.hypot(z.x-x,z.y-y);if(d<bd){bd=d;best=z}}return best}
function shoot(x,y,target,color,damage,speed=11){if(!target)return;const dx=target.x-x,dy=target.y-y,d=Math.hypot(dx,dy)||1;state.bullets.push({x,y,vx:dx/d*speed,vy:dy/d*speed,damage,color,life:d/speed+.1})}
function movePlayer(p,dx,dy,dt){if(!dx&&!dy)return;const norm=Math.hypot(dx,dy)||1;dx=dx/norm*p.speed*dt;dy=dy/norm*p.speed*dt;const can=(x,y)=>{if(x<.5||y<.5||x>cols-1.5||y>rows-1.5)return false;const gx=Math.floor(x),gy=Math.floor(y);return !state.builds.some(b=>b.type==='wall'&&b.x===gx&&b.y===gy)};if(can(p.x+dx,p.y))p.x+=dx;if(can(p.x,p.y+dy))p.y+=dy}
function hitZombie(z,damage){z.hp-=damage;z.hit=.14;if(z.hp<=0){state.kills++;if(Math.random()<.36){state.scrap+=2;updateCards()}if(Math.random()<.22)state.food++;state.zombies.splice(state.zombies.indexOf(z),1);$('statusLine').textContent=state.kills+' infected neutralized · keep the tower safe.'}}
function update(dt){if(!state.running||state.paused)return;state.phaseTime-=dt;if(state.phase==='day'){
 state.gatherTimer+=dt;if(state.gatherTimer>=6){state.gatherTimer=0;state.wood+=4;state.scrap+=2;state.food+=2;state.builds.filter(b=>b.type==='garden').forEach(()=>{state.food+=2});updateHud();updateCards()}
 if(state.phaseTime<=0)startPhase();
 }else{
 state.spawnTimer-=dt;if(state.spawnTimer<=0&&state.zombies.length<16){spawnZombie();state.spawnTimer=Math.max(1.05,2.4-state.day*.16)+rand(0,.8)}if(state.phaseTime<=0&&state.zombies.length===0){morning()}
 }
 const players=state.players.filter((p,i)=>i===0||state.mode==='duo');players.forEach((p,i)=>{p.cool=Math.max(0,p.cool-dt);let dx=0,dy=0;if(i===0){dx=(keys.has('d')?1:0)-(keys.has('a')?1:0);dy=(keys.has('s')?1:0)-(keys.has('w')?1:0)}else{dx=(keys.has('arrowright')?1:0)-(keys.has('arrowleft')?1:0);dy=(keys.has('arrowdown')?1:0)-(keys.has('arrowup')?1:0)}movePlayer(p,dx,dy,dt);const attack=keys.has(i===0?' ':'enter');if(attack&&p.cool<=0){const z=nearestZombie(p.x,p.y,5.4);if(z){shoot(p.x+.5,p.y+.5,z,p.color,26,13);p.cool=.38}}});
 // Auto sentries
 state.builds.filter(b=>b.type==='turret').forEach(b=>{b.cool-=dt;if(b.cool<=0){const z=nearestZombie(b.x+.5,b.y+.5,6);if(z){shoot(b.x+.5,b.y+.5,z,'#d7e89a',24,10);b.cool=.85}}});
 state.bullets.forEach(b=>{b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;for(const z of [...state.zombies])if(Math.hypot(z.x+.5-b.x,z.y+.5-b.y)<.42){hitZombie(z,b.damage);b.life=-1;break}});state.bullets=state.bullets.filter(b=>b.life>0&&b.x>0&&b.y>0&&b.x<cols&&b.y<rows);
 state.zombies.forEach(z=>{z.hit=Math.max(0,z.hit-dt);z.cool-=dt;let target=null,targetD=99;for(const p of players){const d=Math.hypot(p.x-z.x,p.y-z.y);if(d<targetD){target=p;targetD=d}}const td=Math.hypot(state.tower.x+.5-z.x,state.tower.y+.5-z.y);if(td<targetD+1.6){target={x:state.tower.x+.5,y:state.tower.y+.5,tower:true};targetD=td}
 let blocked=null;for(const b of state.builds){if(b.type==='wall'&&Math.hypot(b.x+.5-z.x,b.y+.5-z.y)<1.02){blocked=b;break}}if(blocked){if(z.cool<=0){blocked.hp-=12;z.cool=.75;if(blocked.hp<=0){state.builds.splice(state.builds.indexOf(blocked),1);showToast('A barricade was breached!')}}return}
 if(targetD<.9){if(z.cool<=0){if(target.tower)state.tower.hp-=z.boss?10:5;else target.hp-=z.boss?16:9;z.cool=.85}return}const dx=target.x-z.x,dy=target.y-z.y,d=Math.hypot(dx,dy)||1;let nx=z.x+dx/d*z.speed*dt,ny=z.y+dy/d*z.speed*dt;const bx=Math.floor(nx),by=Math.floor(ny);if(state.builds.some(b=>b.type==='wall'&&b.x===bx&&b.y===by)){return}z.x=nx;z.y=ny;});
 if(state.tower.hp<=0){finish(false);return}if(players.every(p=>p.hp<=0)){finish(false);return}if(state.phase==='night'&&state.phaseTime<=0&&state.zombies.length===0)morning();updateHud();draw();}
