$('pauseBtn').addEventListener('click',togglePause);$('startBtn').addEventListener('click',togglePause);$('restartBtn').addEventListener('click',()=>{if(state.running){state.paused=true;draw()}$('startOverlay').classList.remove('hidden')});$('againBtn').addEventListener('click',()=>{$('endOverlay').classList.add('hidden');$('startOverlay').classList.remove('hidden')});$('soundBtn').addEventListener('click',()=>{const on=$('soundBtn').dataset.on!=='1';$('soundBtn').dataset.on=on?'1':'0';$('soundBtn').style.color=on?'var(--lime)':'#b5c1b8';showToast(on?'Sound effects enabled':'Sound effects muted')});
updateHud();updateCards();draw();
})();
</script>
